INSERT INTO products (slug, name, description, details, specs, options, category, price_cents, image_url, tint, in_stock, sort_order) VALUES


  ('french-fries', 'French Fries', 'Golden fries, cut thin and fried to order, salted the moment they come up.', 'Cut thin and fried twice: once to cook them through, again to crisp the outside. That second fry is why they stay crisp on the way to you instead of steaming soft in the box. Salted the moment they come out of the oil, while the surface still holds it. Served with ketchup; ask for chilli garlic instead if you prefer.', '{"Portion":"Regular","Serves":"1–2","Cut":"Thin, twice-fried","Served with":"Ketchup"}', '[{"key":"cold_drink","label":"Cold drink","desc":"500ml","price_cents":10000}]', 'Food & Drinks', 35000, 'https://images.pexels.com/photos/5779487/pexels-photo-5779487.jpeg?auto=compress&cs=tinysrgb&w=800', '#E8DDF2', 1, 5),
  ('zinger-burger', 'Zinger Burger', 'Buttermilk-marinated chicken fillet in a crisp spiced crust, in a soft sesame bun.', 'A single chicken fillet, marinated overnight in buttermilk so it stays juicy, then dredged in a spiced flour crust and fried until it shatters. The bun is toasted so it holds up under the sauce without going soggy. Lettuce and mayo as standard; the heat is mild rather than hot.', '{"Serves":"1","Filling":"Chicken fillet","Heat":"Mild","Bun":"Toasted sesame"}', '[{"key":"cold_drink","label":"Cold drink","desc":"500ml","price_cents":10000}]', 'Food & Drinks', 55000, 'https://images.pexels.com/photos/17121731/pexels-photo-17121731.jpeg?auto=compress&cs=tinysrgb&w=800', '#CFC3E3', 1, 6),
  ('roti', 'Roti', 'Hand-rolled whole-wheat flatbread, cooked fresh on the tawa.', 'Hand-rolled and cooked to order on a hot tawa, then held briefly over the flame so it puffs and stays soft rather than turning brittle. Whole-wheat flour and no shortening, and no oil brushed on at the end, so it is as good with a dry kebab as with a curry.', '{"Pieces":"2","Flour":"Whole wheat","Cooked":"Fresh on the tawa","No":"Shortening or oil"}', 'https://images.pexels.com/photos/12427834/pexels-photo-12427834.jpeg?auto=compress&cs=tinysrgb&w=800', 'Food & Drinks', 8000, 'https://images.pexels.com/photos/12427834/pexels-photo-12427834.jpeg?auto=compress&cs=tinysrgb&w=800', '#D9CCEA', 1, 7),
  ('stoneware-mug', 'Stoneware Mug', 'Glazed stoneware, holds heat well and goes in the dishwasher.', 'Thrown in small batches and glazed inside and out, so it holds heat as well as it looks doing it. The foot is left unglazed, which stops it sticking to a shelf or a table. The handle is pulled rather than attached, so there is no seam to crack.', '{"Capacity":"350 ml","Dimensions":"9 cm high x 8 cm wide","Weight":"320 g","Material":"Glazed stoneware","Care":"Dishwasher and microwave safe"}', 'https://images.pexels.com/photos/18724166/pexels-photo-18724166.jpeg?auto=compress&cs=tinysrgb&w=800', 'Kitchen', 780000, 'https://images.pexels.com/photos/18724166/pexels-photo-18724166.jpeg?auto=compress&cs=tinysrgb&w=800', '#D9CCEA', 1, 10),
  ('linen-throw', 'Linen Throw', 'Woven European flax, softens with every wash.', 'Woven from European flax and washed before it leaves us, so it arrives already soft rather than needing a break-in period. Heavy enough to sit over the back of a chair without sliding. The selvedge is finished by hand.', '{"Dimensions":"130 x 180 cm","Weight":"1.1 kg","Material":"100% European flax linen","Care":"Machine wash at 40C, line dry"}', 'https://images.pexels.com/photos/27515155/pexels-photo-27515155.jpeg?auto=compress&cs=tinysrgb&w=800', 'Textiles', 1780000, 'https://images.pexels.com/photos/27515155/pexels-photo-27515155.jpeg?auto=compress&cs=tinysrgb&w=800', '#E8DDF2', 1, 20),
  ('glass-carafe', 'Glass Carafe', 'Borosilicate glass with a cork stopper, pours without dripping.', 'Borosilicate, so it survives a hot liquid being poured straight into it. The cork is a natural stopper with a silicone ring underneath to keep it watertight. The spout is narrow enough to pour clean without running down the side.', '{"Capacity":"1 litre","Dimensions":"28 cm high x 9 cm wide","Weight":"480 g","Material":"Borosilicate glass, natural cork","Care":"Dishwasher safe, hand wash the cork"}', 'https://images.pexels.com/photos/1002781/pexels-photo-1002781.jpeg?auto=compress&cs=tinysrgb&w=800', 'Kitchen', 1170000, 'https://images.pexels.com/photos/1002781/pexels-photo-1002781.jpeg?auto=compress&cs=tinysrgb&w=800', '#CFC3E3', 1, 30),
  ('soy-candle', 'Soy Candle', 'Rapeseed and coconut wax, unscented, about 40 hours of burn.', 'Unscented, so it does not compete with a room or a meal. The wick is cotton and lead-free, and the wax is a rapeseed and coconut blend rather than paraffin, which burns cleaner and keeps its shape in a warm room.', '{"Burn time":"Approx. 40 hours","Net weight":"220 g","Dimensions":"8 cm high x 7 cm diameter","Material":"Rapeseed and coconut wax, cotton wick","Care":"Trim the wick to 5 mm before each burn"}', 'https://images.pexels.com/photos/6634662/pexels-photo-6634662.jpeg?auto=compress&cs=tinysrgb&w=800', 'Candles', 670000, 'https://images.pexels.com/photos/6634662/pexels-photo-6634662.jpeg?auto=compress&cs=tinysrgb&w=800', '#E3D6EE', 1, 40),
  ('ceramic-vase', 'Ceramic Vase', 'Wheel-thrown stoneware with a matte white glaze.', 'Wheel-thrown, so no two are identical in a small way: the rim will not be perfectly even, and that is the point of it. Matte white glaze outside, unglazed foot. Holds a full bunch of cut flowers or a single branch.', '{"Height":"26 cm","Mouth diameter":"9 cm","Weight":"740 g","Material":"Stoneware, matte white glaze","Care":"Wipe with a damp cloth"}', 'https://images.pexels.com/photos/7119222/pexels-photo-7119222.jpeg?auto=compress&cs=tinysrgb&w=800', 'Decor', 1560000, 'https://images.pexels.com/photos/7119222/pexels-photo-7119222.jpeg?auto=compress&cs=tinysrgb&w=800', '#E3D6EE', 1, 50),
  ('wool-cushion', 'Wool Cushion', 'Lambswool cover with a feather-down insert, 45cm square.', 'Lambswool cover with a feather-down insert, filled firm enough to sit upright on a chair rather than slumping. The cover unzips at the back for washing. The feather is washable, so it can be refilled rather than replaced.', '{"Dimensions":"45 x 45 cm","Weight":"900 g","Fill":"Feather down","Cover":"Lambswool, removable","Care":"Cover dry clean, fluff by hand"}', 'https://images.pexels.com/photos/4846361/pexels-photo-4846361.jpeg?auto=compress&cs=tinysrgb&w=800', 'Textiles', 1330000, 'https://images.pexels.com/photos/4846361/pexels-photo-4846361.jpeg?auto=compress&cs=tinysrgb&w=800', '#CFC3E3', 1, 60),
  ('serving-bowl', 'Serving Bowl', 'Shallow glazed bowl, nests with the others to save shelf space.', 'Wide and shallow, which is what makes it a serving bowl rather than a mixing bowl: the food stays visible and easy to reach across a table. Glazed inside, so it takes a sauce without soaking it in. Nests with the others.', '{"Capacity":"2.5 litres","Dimensions":"9 cm high x 28 cm wide","Weight":"1.3 kg","Material":"Glazed stoneware","Care":"Dishwasher safe"}', 'https://images.pexels.com/photos/5472025/pexels-photo-5472025.jpeg?auto=compress&cs=tinysrgb&w=800', 'Kitchen', 1000000, 'https://images.pexels.com/photos/5472025/pexels-photo-5472025.jpeg?auto=compress&cs=tinysrgb&w=800', '#E8DDF2', 1, 70),
  ('stoneware-pitcher', 'Stoneware Pitcher', 'A heavy stoneware pitcher for water or wine, glazed in a soft matte cream.', 'Glazed inside and out in a matte cream, so nothing tastes of the clay. The handle is pulled rather than attached, so there is no seam to crack, and the lip is unglazed on the inside only where the glaze would pool. Holds 1.2 litres, which is enough for four glasses.', '{"Capacity":"1.2 litres","Dimensions":"22 cm high x 14 cm wide","Weight":"860 g","Material":"Glazed stoneware","Care":"Dishwasher and microwave safe"}', 'https://images.pexels.com/photos/6963838/pexels-photo-6963838.jpeg?auto=compress&cs=tinysrgb&w=800', 'Kitchen', 2450000, 'https://images.pexels.com/photos/6963838/pexels-photo-6963838.jpeg?auto=compress&cs=tinysrgb&w=800', '#E8DDF2', 1, 70),
  ('brass-tray', 'Brass Tray', 'Unlacquered brass that darkens to a deeper patina over time.', 'Unlacquered brass, left uncoated so it darkens to a deeper patina as it is handled instead of staying permanently shiny. Made for keys, a watch, or a small pile of odds and ends. It will not return to bright.', '{"Dimensions":"28 x 18 cm","Weight":"640 g","Material":"Unlacquered brass","Care":"Dry wipe, the patina is intended"}', 'https://images.pexels.com/photos/18710350/pexels-photo-18710350.jpeg?auto=compress&cs=tinysrgb&w=800', 'Decor', 1450000, 'https://images.pexels.com/photos/18710350/pexels-photo-18710350.jpeg?auto=compress&cs=tinysrgb&w=800', '#D9CCEA', 1, 80)


ON CONFLICT (slug) DO UPDATE SET


